import{_ as e,o as r,c as i,a2 as t}from"./chunks/framework.BW2T23B9.js";const f=JSON.parse('{"title":"核心能力一览","description":"先看这一页建立地图，细节进各功能页。产品主页的卡片和预览对应同一套能力。","frontmatter":{"description":"先看这一页建立地图，细节进各功能页。产品主页的卡片和预览对应同一套能力。"},"headers":[],"relativePath":"guide/features.md","filePath":"guide/features.md","lastUpdated":1787830168000}'),o={name:"guide/features.md"};function l(d,a,s,n,h,c){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="核心能力一览" tabindex="-1">核心能力一览 <a class="header-anchor" href="#核心能力一览" aria-label="Permalink to &quot;核心能力一览&quot;">​</a></h1><p>先看这一页建立地图，细节进各功能页。产品主页的卡片和预览对应同一套能力。</p><h2 id="离线与本地优先" tabindex="-1">离线与本地优先 <a class="header-anchor" href="#离线与本地优先" aria-label="Permalink to &quot;离线与本地优先&quot;">​</a></h2><ul><li>课程与学习记录存在设备上，关掉网络也能学和复习。</li><li>只在你主动同步或更新时联网，默认不上传学习记录。</li><li>无需账号，没有广告、排行榜或付费墙。</li></ul><h2 id="fsrs-智能复习" tabindex="-1">FSRS 智能复习 <a class="header-anchor" href="#fsrs-智能复习" aria-label="Permalink to &quot;FSRS 智能复习&quot;">​</a></h2><p>内置开源 FSRS：Anki 牌组走 <code>fsrs-rs</code>，课程词走 Dart 实现，都是 21 参数的 FSRS-6。详见 <a href="/docs/guide/fsrs">FSRS 复习</a>。</p><h2 id="anki-兼容" tabindex="-1">Anki 兼容 <a class="header-anchor" href="#anki-兼容" aria-label="Permalink to &quot;Anki 兼容&quot;">​</a></h2><p>复用官方 Anki 内核。<code>.apkg</code> 导入后进入课程路径，并与复习共用学习记录。详见 <a href="/docs/guide/anki">Anki 集成</a>。</p><h2 id="ai-伴学" tabindex="-1">AI 伴学 <a class="header-anchor" href="#ai-伴学" aria-label="Permalink to &quot;AI 伴学&quot;">​</a></h2><p>跟课答疑、分层提示、按错题和弱词出练习。不配模型时用本地课程片段讲解。详见 <a href="/docs/guide/ai">AI 伴学</a>。</p><h2 id="课程编辑器" tabindex="-1">课程编辑器 <a class="header-anchor" href="#课程编辑器" aria-label="Permalink to &quot;课程编辑器&quot;">​</a></h2><p>桌面 <code>tool/gui</code> 编辑 Section / Unit / Lesson，保存时校验 JSON。详见 <a href="/docs/guide/editor">课程编辑器</a> 与 <a href="/docs/authoring/teacher-guide">教师指南</a>。</p><h2 id="开源与可定制" tabindex="-1">开源与可定制 <a class="header-anchor" href="#开源与可定制" aria-label="Permalink to &quot;开源与可定制&quot;">​</a></h2><p>MIT 协议，源自 <a href="https://github.com/rshrc/Varnamala" target="_blank" rel="noreferrer">rshrc/Varnamala</a>。主题「晨雾 / 夕光」可在产品主页切换。</p><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to &quot;推荐阅读顺序&quot;">​</a></h2><ol><li><a href="/docs/guide/getting-started">快速开始</a></li><li><a href="/docs/guide/curriculum">课程结构</a></li><li>按需要进入 FSRS / Anki / AI / 编辑器</li></ol>',16)])])}const p=e(o,[["render",l]]);export{f as __pageData,p as default};
